insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id from jsonb_to_recordset($bank$[{"id":"che-st-141","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Potassium chlorate $\\mathrm{KClO_3}$ (M = 122.5 g mol$^{-1}$) releases oxygen on heating. Oxygen’s mass percent in $\\mathrm{KClO_3}$ is nearest to","options":["13.1%","26.1%","39.2%","52.2%"],"answer_index":2,"explanation":"Three oxygen atoms weigh 48 g in 122.5 g, giving $48/122.5 \\times 100 \\approx 39.2\\%$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"molar-mass-percent"},{"id":"che-st-142","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"From a 50 g laboratory sample of pure $\\mathrm{CaCO_3}$, the mass of oxygen that can be accounted for in the formula is","options":["16 g","24 g","32 g","48 g"],"answer_index":1,"explanation":"Oxygen is 48% of $\\mathrm{CaCO_3}$, so $0.48 \\times 50 = 24$ g.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"molar-mass-percent"},{"id":"che-st-143","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Blue vitriol $\\mathrm{CuSO_4 \\cdot 5H_2O}$ (M = 249.5 g mol$^{-1}$) loses its water of crystallisation on strong heating. The mass percent of water in the pentahydrate is nearest to","options":["18.0%","25.0%","36.1%","45.2%"],"answer_index":2,"explanation":"Five water molecules weigh 90 g in 249.5 g, so $90/249.5 \\times 100 \\approx 36.1\\%$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"molar-mass-percent"},{"id":"che-st-144","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Haematite $\\mathrm{Fe_2O_3}$ (M = 160 g mol$^{-1}$) is 70% iron by mass. An 80 g ore sample that is 80% pure $\\mathrm{Fe_2O_3}$ (rest gangue) contains iron weighing","options":["44.8 g","56.0 g","64.0 g","70.0 g"],"answer_index":0,"explanation":"Pure oxide in the ore is $0.80 \\times 80 = 64$ g; iron in that oxide is $0.70 \\times 64 = 44.8$ g.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"molar-mass-percent"},{"id":"che-st-145","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The empirical formula of a compound is the formula that shows","options":["the actual number of atoms in one molecule","the simplest whole-number ratio of the atoms present","only the metals in the compound","the percentage by mass of each element"],"answer_index":1,"explanation":"Empirical formulae give the smallest integer atom ratio, not necessarily the molecular formula.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"empirical-molecular"},{"id":"che-st-146","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A molecular formula is related to the empirical formula by a positive integer $n$ such that","options":["molecular formula $= n \\times$ empirical formula","empirical formula $= n \\times$ molecular formula","$n$ equals the number of elements","$n$ is always 1 for covalent compounds"],"answer_index":0,"explanation":"$n = M / $ (empirical formula mass), and the molecular formula is that multiple of the empirical set.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"empirical-molecular"},{"id":"che-st-147","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Benzene has molecular formula $\\mathrm{C_6H_6}$. Its empirical formula is therefore","options":["$\\mathrm{CH}$","$\\mathrm{C_2H_2}$","$\\mathrm{C_6H_6}$","$\\mathrm{C_3H_3}$"],"answer_index":0,"explanation":"Dividing $\\mathrm{C_6H_6}$ by 6 gives the simplest ratio CH.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"empirical-molecular"},{"id":"che-st-148","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Glucose, $\\mathrm{C_6H_{12}O_6}$, reduces to the empirical set","options":["$\\mathrm{CHO}$","$\\mathrm{CH_2O}$","$\\mathrm{C_2H_4O_2}$","$\\mathrm{C_6H_{12}O_6}$"],"answer_index":1,"explanation":"Each subscript is divisible by 6, leaving CH$_2$O.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"empirical-molecular"},{"id":"che-st-149","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Hydrogen peroxide $\\mathrm{H_2O_2}$ has the empirical formula","options":["$\\mathrm{HO}$","$\\mathrm{H_2O}$","$\\mathrm{HO_2}$","$\\mathrm{H_2O_2}$"],"answer_index":0,"explanation":"The simplest H : O ratio in hydrogen peroxide is 1 : 1, written HO.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"empirical-molecular"},{"id":"che-st-150","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"An organic gas has empirical formula $\\mathrm{CH_2}$ and a molar mass of 56 g mol$^{-1}$. Its molecular formula is","options":["$\\mathrm{C_2H_4}$","$\\mathrm{C_3H_6}$","$\\mathrm{C_4H_8}$","$\\mathrm{C_5H_{10}}$"],"answer_index":2,"explanation":"Empirical mass is 14; $n = 56/14 = 4$, so the molecule is $\\mathrm{C_4H_8}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"empirical-molecular"},{"id":"che-st-151","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The integer $n$ that converts an empirical formula into the molecular formula is calculated as","options":["empirical mass / molecular mass","molecular mass / empirical formula mass","atomic number / mass number","percentage of carbon / 12"],"answer_index":1,"explanation":"$n = M / E$, then each empirical subscript is multiplied by $n$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"empirical-molecular"},{"id":"che-st-152","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"For an ionic solid such as $\\mathrm{Na_2CO_3}$, the formula written on the bottle is already","options":["a molecular formula that can be halved","the empirical formula of the compound","only a percentage composition","an unbalanced equation"],"answer_index":1,"explanation":"Ionic compounds are represented by the simplest ratio of ions, which is the empirical formula.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"empirical-molecular"},{"id":"che-st-153","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A hydrocarbon analyses as 80% carbon and 20% hydrogen by mass. Its empirical formula is","options":["$\\mathrm{CH}$","$\\mathrm{CH_2}$","$\\mathrm{CH_3}$","$\\mathrm{C_2H_5}$"],"answer_index":2,"explanation":"Mole ratio C : H $= (80/12) : (20/1) = 6.67 : 20 = 1 : 3$, so $\\mathrm{CH_3}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"empirical-molecular"},{"id":"che-st-154","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A compound contains 40.0% C, 6.7% H and 53.3% O. The empirical formula matching these percentages is","options":["$\\mathrm{CHO}$","$\\mathrm{CH_2O}$","$\\mathrm{C_2H_2O}$","$\\mathrm{C_2H_6O}$"],"answer_index":1,"explanation":"Moles C : H : O $= 3.33 : 6.7 : 3.33 = 1 : 2 : 1$, which is $\\mathrm{CH_2O}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"empirical-molecular"},{"id":"che-st-155","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A vapour has empirical formula CH and a vapour density corresponding to $M = 78$ g mol$^{-1}$. The molecular formula of the vapour is","options":["$\\mathrm{C_2H_2}$","$\\mathrm{C_3H_3}$","$\\mathrm{C_6H_6}$","$\\mathrm{C_{12}H_{12}}$"],"answer_index":2,"explanation":"Empirical mass 13; $n = 78/13 = 6$, giving $\\mathrm{C_6H_6}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"empirical-molecular"},{"id":"che-st-156","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"An iron oxide is 70% Fe and 30% O by mass (Fe = 56, O = 16). The oxide’s empirical formula is","options":["$\\mathrm{FeO}$","$\\mathrm{Fe_2O_3}$","$\\mathrm{Fe_3O_4}$","$\\mathrm{FeO_2}$"],"answer_index":1,"explanation":"Moles Fe : O $= (70/56) : (30/16) = 1.25 : 1.875 = 2 : 3$, so $\\mathrm{Fe_2O_3}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"empirical-molecular"},{"id":"che-st-157","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A hydrocarbon is 85.7% carbon, the rest hydrogen. The empirical formula of that hydrocarbon is","options":["$\\mathrm{CH}$","$\\mathrm{CH_2}$","$\\mathrm{CH_3}$","$\\mathrm{C_2H_2}$"],"answer_index":1,"explanation":"C : H moles $= (85.7/12) : (14.3/1) \\approx 7.14 : 14.3 = 1 : 2$, hence $\\mathrm{CH_2}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"empirical-molecular"},{"id":"che-st-158","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A chloro-compound is 24.24% C, 4.04% H and 71.72% Cl. Its molar mass is 99 g mol$^{-1}$. The molecular formula is","options":["$\\mathrm{CH_2Cl}$","$\\mathrm{C_2H_4Cl_2}$","$\\mathrm{C_2H_3Cl}$","$\\mathrm{C_3H_6Cl_2}$"],"answer_index":1,"explanation":"Empirical moles give $\\mathrm{CH_2Cl}$ (E = 49.5); $n = 99/49.5 = 2$, so $\\mathrm{C_2H_4Cl_2}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"empirical-molecular"},{"id":"che-st-159","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"In the Haber equation $\\mathrm{N_2} + 3\\mathrm{H_2} \\rightarrow 2\\mathrm{NH_3}$, each mole of nitrogen that reacts consumes hydrogen amounting to","options":["1 mol","2 mol","3 mol","6 mol"],"answer_index":2,"explanation":"The coefficient of $\\mathrm{H_2}$ is 3, so the mole ratio N$_2$ : H$_2$ is 1 : 3.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio"},{"id":"che-st-160","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"According to $2\\mathrm{H_2} + \\mathrm{O_2} \\rightarrow 2\\mathrm{H_2O}$, complete use of 1 mol of oxygen produces water equal to","options":["1 mol","2 mol","0.5 mol","4 mol"],"answer_index":1,"explanation":"One mole of $\\mathrm{O_2}$ corresponds to two moles of $\\mathrm{H_2O}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio"}]$bank$::jsonb) as t(id text, chapter_id text, subject_id text, stem text, options jsonb, answer_index int, explanation text, images jsonb, source jsonb, difficulty text, concept_id text) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
insert into question_pyq_meta (question_id, appear_count, years, exams, verified) select question_id, appear_count, years, exams, verified from jsonb_to_recordset($meta$[{"question_id":"che-st-141","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-142","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-143","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-144","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-145","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-146","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-147","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-148","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-149","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-150","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-151","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-152","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-153","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-154","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-155","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-156","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-157","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-158","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-159","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-160","appear_count":0,"years":[],"exams":[],"verified":false}]$meta$::jsonb) as t(question_id text, appear_count int, years int[], exams text[], verified boolean) on conflict (question_id) do update set appear_count = excluded.appear_count, years = excluded.years, exams = excluded.exams, verified = excluded.verified;
